366	/**
367	 * Validate git ref to prevent command injection
368	 * Only allows safe characters: alphanumeric, -, _, /, ., ~, ^
369	 */
370	function validateGitRef(ref: string): void {
371	  // Block shell metacharacters and dangerous patterns
372	  if (!/^[a-zA-Z0-9_\-./~^@]+$/.test(ref)) {
373	    throw new Error(`Invalid git ref: contains unsafe characters`);
374	  }
375	  // Block multiple dots (path traversal)
376	  if (ref.includes('..') && !ref.match(/^[a-zA-Z0-9_\-]+\.\.\.?[a-zA-Z0-9_\-]+$/)) {
377	    if (!/^\w+\.\.[.\w]+$/.test(ref)) {
378	      throw new Error(`Invalid git ref: suspicious pattern`);
379	    }
380	  }
381	  // Max length check
382	  if (ref.length > 256) {
383	    throw new Error(`Invalid git ref: too long`);
384	  }
385	}
