387	/**
388	 * Get git diff statistics using SINGLE combined command (optimized)
389	 * Replaces two separate git commands with one
390	 */
391	export function getGitDiffNumstat(ref: string = 'HEAD'): DiffFile[] {
392	  // SECURITY: Validate git ref to prevent command injection
393	  validateGitRef(ref);
394	
395	  // Check cache first
396	  const cacheKey = `numstat:${ref}`;
397	  const cached = diffCache.get(cacheKey);
398	  if (cached && Date.now() - cached.timestamp < CACHE_TTL_MS) {
399	    return cached.files;
400	  }
401	
402	  // execFileSync imported at top level
403	  try {
404	    // SECURITY: Use execFileSync with args array instead of shell string
405	    // This prevents command injection via the ref parameter
406	    const numstatOutput = execFileSync('git', [
407	      'diff', '--numstat', '--diff-filter=ACDMRTUXB', ref
408	    ], { encoding: 'utf-8', maxBuffer: 10 * 1024 * 1024 });
