120	async function cachedReadFile(filePath: string): Promise<string> {
121	  const cached = fileCache.get(filePath);
122	  const now = Date.now();
123	
124	  if (cached && cached.expires > now) {
125	    return cached.content;
126	  }
127	
128	  const content = await fs.readFile(filePath, 'utf-8');
129	  fileCache.set(filePath, {
130	    content,
131	    expires: now + FILE_CACHE_TTL,
132	  });
133	
134	  // Cleanup old entries periodically (keep cache small)
135	  if (fileCache.size > 100) {
136	    for (const [key, entry] of fileCache) {
137	      if (entry.expires < now) {
138	        fileCache.delete(key);
139	      }
140	    }
141	  }
142	
143	  return content;
144	}
